tasks = set(r[0] for r in rows_data)
workers = set(r[1] for r in rows_data)
cost_dict = {(r[0], r[1]): r[2] for r in rows_data}
all_tasks = list(tasks)
all_workers = list(workers)
from itertools import permutations
min_cost = float('inf')
max_covered = 0
for r in range(1, len(all_workers) + 1):
    for p_tasks in permutations(all_tasks, r):
        for p_workers in permutations(all_workers, r):
            possible = True
            c = 0
            for t, w in zip(p_tasks, p_workers):
                if (t, w) not in cost_dict:
                    possible = False
                    break
                c += cost_dict[(t, w)]
            if possible:
                if r > max_covered:
                    max_covered = r
result = max_covered

